package com.coffeeshop.controller;import com.coffeeshop.model.DocumentModels.*;import com.coffeeshop.security.ApplicationSession;import com.coffeeshop.service.DocumentService;import javafx.application.Platform;import javafx.beans.property.SimpleStringProperty;import javafx.fxml.FXML;import javafx.scene.control.*;import java.util.*;import java.util.concurrent.CompletableFuture;public final class DocumentsController{private final DocumentService service;private final ApplicationSession session;@FXML private ComboBox<Order>orderBox;@FXML private ChoiceBox<String>typeBox;@FXML private TableView<Document>documentTable;@FXML private TableColumn<Document,String>numberColumn,orderColumn,typeColumn,issuedColumn,customerColumn,totalColumn,userColumn;@FXML private Label messageLabel;@FXML private TextArea detailArea;public DocumentsController(DocumentService s,ApplicationSession a){service=Objects.requireNonNull(s);session=Objects.requireNonNull(a);}@FXML private void initialize(){typeBox.getItems().setAll("RECEIPT","INVOICE");typeBox.setValue("RECEIPT");numberColumn.setCellValueFactory(v->text(v.getValue().number()));orderColumn.setCellValueFactory(v->text(v.getValue().orderNumber()));typeColumn.setCellValueFactory(v->text(v.getValue().type().replace('_',' ')));issuedColumn.setCellValueFactory(v->text(v.getValue().issuedAt().toString().replace('T',' ')));customerColumn.setCellValueFactory(v->text(first(v.getValue().business(),v.getValue().customer(),"Walk-in")));totalColumn.setCellValueFactory(v->text(v.getValue().total().toPlainString()));userColumn.setCellValueFactory(v->text(v.getValue().issuedBy()));documentTable.getSelectionModel().selectedItemProperty().addListener((o,a,b)->details(b));refresh();}@FXML private void refresh(){CompletableFuture.supplyAsync(service::catalog).whenComplete((v,e)->Platform.runLater(()->{if(e!=null){messageLabel.setText("Unable to load documents.");return;}orderBox.getItems().setAll(v.orders());documentTable.getItems().setAll(v.documents());messageLabel.setText(v.documents().isEmpty()?"No receipts or invoices have been issued.":"");details(documentTable.getSelectionModel().getSelectedItem());}));}@FXML private void issue(){Order o=orderBox.getValue();if(o==null){messageLabel.setText("Select a completed order.");return;}CompletableFuture.runAsync(()->service.issue(o.id(),typeBox.getValue(),session.currentUser().orElseThrow().userId())).whenComplete((v,e)->Platform.runLater(()->{if(e==null){refresh();messageLabel.setText("Document issued.");}else messageLabel.setText(message(e));}));}private void details(Document d){if(d==null){detailArea.clear();return;}detailArea.setText("Document: "+d.number()+"\nOrder: "+d.orderNumber()+"\nType: "+d.type()+"\nIssued: "+d.issuedAt()+"\nCustomer: "+first(d.customer(),"Walk-in")+"\nBusiness: "+first(d.business(),"-")+"\nTax registration: "+first(d.taxNumber(),"-")+"\nBilling address: "+first(d.address(),"-")+"\n\nSubtotal: "+d.subtotal()+"\nDiscount: "+d.discount()+"\nTax: "+d.tax()+"\nTotal: "+d.total());}private static String first(String...v){for(String x:v)if(x!=null&&!x.isBlank())return x;return "";}private static SimpleStringProperty text(String s){return new SimpleStringProperty(s);}private static String message(Throwable e){Throwable x=e;while(x.getCause()!=null)x=x.getCause();return x instanceof IllegalArgumentException||x instanceof IllegalStateException?x.getMessage():"Unable to issue document.";}}
